import { bucketCount } from "./result-telemetry.js";

const EXERCISE_TEMPLATE_CATALOG_CACHE_KEY = "exercise-template-catalog";
const EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS = 5 * 60 * 1000;
const EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE = 1;

export type ExerciseTemplateCatalogRefreshReason =
	| "explicit-refresh"
	| "initial-load"
	| "ttl-expired";

export interface ExerciseTemplateCatalogOptions {
	refresh?: boolean;
	execution?: HevyRequestOptions;
	onRefreshed?: (
		catalog: ExerciseTemplate[],
		reason: ExerciseTemplateCatalogRefreshReason,
	) => void;
}

export interface ExerciseTemplateCatalog {
	get(options?: ExerciseTemplateCatalogOptions): Promise<ExerciseTemplate[]>;
	reset(): void;
}

export function createExerciseTemplateCatalog(
	hevyClient: Pick<HevyClient, "getExerciseTemplates">,
	cacheObserver?: CacheObserver,
): ExerciseTemplateCatalog {
	const cache = new AsyncTtlCache<string, ExerciseTemplate[]>({
		ttlMs: EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS,
		maxSize: EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE,
		observer: cacheObserver,
	});

	return {
		get(options = {}) {
			const reason = options.refresh
				? "explicit-refresh"
				: cache.size === 0
					? "initial-load"
					: "ttl-expired";
			let observationMetadata: CacheObservationMetadata | undefined;
			let pagesLoaded = 0;
			return cache.getOrFetch(
				EXERCISE_TEMPLATE_CATALOG_CACHE_KEY,
				async () => {
					const catalog = await fetchAllPages<ExerciseTemplate>(
						async (page, pageSize) => {
							pagesLoaded = page;
							const data: GetV1ExerciseTemplates200 =
								await hevyClient.getExerciseTemplates(
									{
										page,
										pageSize,
									},
									options.execution,
								);
							return {
								items: data?.exercise_templates ?? [],
								pageCount: data?.page_count,
							};
						},
						100,
					);
					observationMetadata = {
						refreshReason: reason,
						pageCountBucket: bucketCount(pagesLoaded),
						itemCountBucket: bucketCount(catalog.length),
					};
					options.onRefreshed?.(catalog, reason);
					return catalog;
				},
				{
					refresh: options.refresh,
					shareInFlight: options.execution === undefined,
					signal: options.execution?.signal,
					deadline: options.execution?.deadline,
					getObservationMetadata: () => observationMetadata,
				},
			);
		},
		reset() {
			cache.clear();
		},
	};
}

import type { JSONSchema } from "zod/v4/core";
import { z } from "zod";
import { isObject, isString } from "./type-predicates.js";
import type { RuntimeValue } from "./type-predicates.js";

type JsonSchema = Omit<JSONSchema.JSONSchema, "type"> & {
	type?: JSONSchema.JSONSchema["type"] | string[];
};

function isRecord(value: RuntimeValue): value is JsonSchema {
	return isObject(value) && !Array.isArray(value);
}

function isNullSchema(value: RuntimeValue): value is JsonSchema {
	return (
		isRecord(value) && value.type === "null" && Object.keys(value).length === 1
	);
}

function compactNullableSchema(value: RuntimeValue): RuntimeValue {
	if (Array.isArray(value)) {
		return value.map(compactNullableSchema);
	}
	if (!isRecord(value)) {
		return value;
	}

	const anyOf = value.anyOf;
	if (Array.isArray(anyOf) && anyOf.length === 2) {
		const nullableBranch = anyOf.find(isNullSchema);
		const valueBranch = anyOf.find((branch) => !isNullSchema(branch));
		if (
			nullableBranch !== undefined &&
			isRecord(valueBranch) &&
			isString(valueBranch.type)
		) {
			const { anyOf: _anyOf, ...metadata } = value;
			return compactNullableSchema({
				...valueBranch,
				...metadata,
				type: [valueBranch.type, "null"],
			});
		}
	}

	return Object.fromEntries(
		Object.entries(value).map(([key, nested]) => [
			key,
			compactNullableSchema(nested),
		]),
	);
}

function omitOutputObjectRestrictions(value: RuntimeValue): RuntimeValue {
	if (Array.isArray(value)) {
		return value.map(omitOutputObjectRestrictions);
	}
	if (!isRecord(value)) {
		return value;
	}
	return Object.fromEntries(
		Object.entries(value)
			.filter(
				([key, nested]) => key !== "additionalProperties" || nested !== false,
			)
			.map(([key, nested]) => [key, omitOutputObjectRestrictions(nested)]),
	);
}

function convertSchema(
	schema: z.ZodTypeAny,
	io: "input" | "output",
): JsonSchema {
	const converted = z.toJSONSchema(schema, {
		target: "draft-2020-12",
		io,
	});
	if (!isRecord(converted)) {
		throw new Error("Zod emitted a non-object root schema");
	}
	const compacted = compactNullableSchema(converted);
	if (!isRecord(compacted)) {
		throw new Error("Nullable schema compaction changed the root schema");
	}
	const output =
		io === "output" ? omitOutputObjectRestrictions(compacted) : compacted;
	if (!isRecord(output)) {
		throw new Error("Output schema compaction changed the root schema");
	}
	delete output.$schema;
	return output;
}

/**
 * Keep Zod validation while advertising a compact JSON Schema.
 *
 * Zod emits nullable values as `anyOf`; draft 2020-12 also permits a type
 * array. The MCP wire envelope does not need a repeated `$schema` marker, and
 * structured output is validated by the original Zod schema before sending.
 */
export function compactJsonSchema<TSchema extends z.ZodTypeAny>(
	schema: TSchema,
): TSchema {
	let inputSchema: JsonSchema | undefined;
	let outputSchema: JsonSchema | undefined;
	Object.defineProperty(schema["~standard"], "jsonSchema", {
		configurable: true,
		value: {
			input: () => {
				inputSchema ??= convertSchema(schema, "input");
				return inputSchema;
			},
			output: () => {
				outputSchema ??= convertSchema(schema, "output");
				return outputSchema;
			},
		},
		writable: true,
	});
	return schema;
}

